import math, datetime

def g(obj, *path):
	for k in path:
		try:
			obj = obj[k]
		except:
			return None
	return obj

def num(v, default=None):
	try:
		return float(v)
	except:
		return default

def localTime(ts, tz):
	if ts is None:
		return '--'
	t = datetime.datetime.utcfromtimestamp(int(ts) + int(tz or 0))
	return t.strftime('%I:%M %p').lstrip('0')

def duration(sec):
	sec = int(abs(sec))
	return '%dh %02dm' % (sec // 3600, (sec % 3600) // 60)

w = value
temp = num(g(w, 'main', 'temp'))
if temp is None:
	return {'ok': False, 'wxClass': 'weather-unknown', 'accent': '#a9b2be', 'icon': 'material/cloud', 'city': 'No data',
			'condition': 'Waiting for data', 'updated': '--', 'temp': '--', 'hiLo': '', 'feelsDetail': '',
			'feels': '--', 'feelsBadge': 'No data', 'feelsBadgeClass': 'badge-offline',
			'humidity': '--', 'humidityPct': '0%', 'humidityDetail': '', 'humidityBadge': 'No data', 'humidityBadgeClass': 'badge-offline',
			'wind': '--', 'windDetail': '', 'windRotation': 0, 'windBadge': 'No data', 'windBadgeClass': 'badge-offline',
			'pressure': '--', 'pressureDetail': '', 'pressureBadge': 'No data', 'pressureBadgeClass': 'badge-offline',
			'visibility': '--', 'visibilityDetail': '', 'visibilityBadge': 'No data', 'visibilityBadgeClass': 'badge-offline',
			'clouds': '--', 'cloudsPct': '0%', 'cloudsDetail': '',
			'precip': '--', 'precipUnit': 'in', 'precipDetail': '', 'precipBadge': 'No data', 'precipBadgeClass': 'badge-offline',
			'sunEvent': '--', 'sunEventLabel': '', 'sunDetail': '', 'sunBadge': 'No data', 'sunBadgeClass': 'badge-offline'}

tz = num(g(w, 'timezone'), 0)
dt = num(g(w, 'dt'))
feels = num(g(w, 'main', 'feels_like'), temp)
hi = num(g(w, 'main', 'temp_max'), temp)
lo = num(g(w, 'main', 'temp_min'), temp)
humidity = num(g(w, 'main', 'humidity'), 0)
pressure = num(g(w, 'main', 'pressure'))
windSpeed = num(g(w, 'wind', 'speed'), 0)
windGust = num(g(w, 'wind', 'gust'))
windDeg = num(g(w, 'wind', 'deg'), 0)
visibility = num(g(w, 'visibility'))
clouds = num(g(w, 'clouds', 'all'), 0)
rainMm = num(g(w, 'rain', '1h'), 0)
snowMm = num(g(w, 'snow', '1h'), 0)
sunrise = num(g(w, 'sys', 'sunrise'))
sunset = num(g(w, 'sys', 'sunset'))
condId = int(num(g(w, 'weather', 0, 'id'), 0))
condDesc = g(w, 'weather', 0, 'description') or ''
iconCode = g(w, 'weather', 0, 'icon') or ''
isNight = iconCode.endswith('n')

# Condition -> stylesheet class + icon
if 200 <= condId < 300:
	wxClass, icon = 'weather-storm', 'material/flash_on'
elif 300 <= condId < 400:
	wxClass, icon = 'weather-drizzle', 'material/grain'
elif 500 <= condId < 600:
	wxClass, icon = 'weather-rain', 'material/umbrella'
elif 600 <= condId < 700:
	wxClass, icon = 'weather-snow', 'material/ac_unit'
elif condId in (771, 781):
	wxClass, icon = 'weather-wind', 'material/toys'
elif 700 <= condId < 800:
	wxClass, icon = 'weather-fog', 'material/waves'
elif condId == 800:
	wxClass, icon = ('weather-night', 'material/nights_stay') if isNight else ('weather-clear', 'material/wb_sunny')
elif condId in (801, 802):
	wxClass, icon = ('weather-night', 'material/nights_stay') if isNight else ('weather-partly-cloudy', 'material/filter_drama')
else:
	wxClass, icon = 'weather-overcast', 'material/cloud'
# Extreme temperature / wind override the calmer sky conditions
if wxClass not in ('weather-storm', 'weather-rain', 'weather-drizzle', 'weather-snow'):
	if temp >= 95:
		wxClass = 'weather-hot'
	elif temp <= 32:
		wxClass = 'weather-cold'
	elif max(windSpeed, windGust or 0) >= 25:
		wxClass, icon = 'weather-wind', 'material/toys'

# Mirrors --wx-accent in stylesheet.css, for components that can't read CSS variables (charts)
accent = {'weather-clear': '#ceab72', 'weather-partly-cloudy': '#c1b082', 'weather-overcast': '#a5b2c5',
		  'weather-rain': '#80bad9', 'weather-storm': '#b4a7e2', 'weather-snow': '#90b8ca',
		  'weather-fog': '#a9b2be', 'weather-wind': '#7ec0b4', 'weather-hot': '#e0a07d',
		  'weather-cold': '#8fb4e4', 'weather-night': '#a4ade4', 'weather-drizzle': '#80bad9'}.get(wxClass, '#a9b2be')

# Feels like
delta = feels - temp
if abs(delta) < 2:
	feelsDetail = 'Close to the actual temperature'
elif delta > 0:
	feelsDetail = u'Humidity makes it feel %d\u00b0 warmer' % round(delta)
else:
	feelsDetail = u'Wind makes it feel %d\u00b0 cooler' % round(-delta)
if feels >= 103:
	feelsBadge, feelsBadgeClass = 'Dangerous heat', 'badge-alarm'
elif feels >= 90:
	feelsBadge, feelsBadgeClass = 'Heat caution', 'badge-warn'
elif feels <= 0:
	feelsBadge, feelsBadgeClass = 'Extreme cold', 'badge-alarm'
elif feels <= 32:
	feelsBadge, feelsBadgeClass = 'Freezing', 'badge-warn'
else:
	feelsBadge, feelsBadgeClass = 'Comfortable', 'badge-ok'

# Humidity / dew point (Magnus formula)
tc = (temp - 32) * 5.0 / 9
rh = max(humidity, 1)
gamma = math.log(rh / 100.0) + 17.62 * tc / (243.12 + tc)
dewF = (243.12 * gamma / (17.62 - gamma)) * 9.0 / 5 + 32
if dewF >= 70:
	humidityBadge, humidityBadgeClass = 'Oppressive', 'badge-alarm'
elif dewF >= 65:
	humidityBadge, humidityBadgeClass = 'Humid', 'badge-warn'
elif dewF >= 60:
	humidityBadge, humidityBadgeClass = 'Sticky', 'badge-warn'
# Dew point is meaningless for comfort in the cold, so fall back to relative humidity
elif humidity >= 85:
	humidityBadge, humidityBadgeClass = 'Damp', 'badge-offline'
elif humidity < 30:
	humidityBadge, humidityBadgeClass = 'Dry', 'badge-offline'
else:
	humidityBadge, humidityBadgeClass = 'Comfortable', 'badge-ok'

# Wind
compass = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW']
windDir = compass[int((windDeg % 360) / 22.5 + 0.5) % 16]
beaufort = [(1, 'Calm'), (4, 'Light air'), (8, 'Light breeze'), (13, 'Gentle breeze'), (19, 'Moderate breeze'),
			(25, 'Fresh breeze'), (32, 'Strong breeze'), (39, 'Near gale'), (47, 'Gale'), (55, 'Strong gale'), (64, 'Storm')]
windName = 'Hurricane force'
for limit, name in beaufort:
	if windSpeed < limit:
		windName = name
		break
windDetail = u'From %s (%d\u00b0)' % (windDir, windDeg)
if windGust:
	windDetail += u' \u00b7 gusts %d mph' % round(windGust)
peakWind = max(windSpeed, windGust or 0)
windBadgeClass = 'badge-alarm' if peakWind >= 32 else ('badge-warn' if peakWind >= 19 else 'badge-ok')

# Pressure
if pressure is None:
	pressureStr, pressureDetail, pressureBadge, pressureBadgeClass = '--', '', 'No data', 'badge-offline'
else:
	pressureStr = '%.2f' % (pressure * 0.02953)
	pressureDetail = '%d hPa' % pressure
	if pressure < 1000:
		pressureBadge, pressureBadgeClass = 'Very low', 'badge-warn'
	elif pressure < 1009:
		pressureBadge, pressureBadgeClass = 'Low', 'badge-offline'
	elif pressure > 1022:
		pressureBadge, pressureBadgeClass = 'High', 'badge-offline'
	else:
		pressureBadge, pressureBadgeClass = 'Normal', 'badge-ok'

# Visibility (API reports meters, capped at 10 km)
if visibility is None:
	visStr, visDetail, visBadge, visBadgeClass = '--', '', 'No data', 'badge-offline'
else:
	visMi = visibility / 1609.34
	visStr = '%.1f' % visMi
	visDetail = '%.1f km' % (visibility / 1000.0) + (' (max reported)' if visibility >= 10000 else '')
	if visMi >= 5:
		visBadge, visBadgeClass = 'Clear', 'badge-ok'
	elif visMi >= 1:
		visBadge, visBadgeClass = 'Reduced', 'badge-warn'
	else:
		visBadge, visBadgeClass = 'Poor', 'badge-alarm'

# Cloud cover
if clouds <= 10:
	cloudsDetail = 'Clear sky'
elif clouds <= 25:
	cloudsDetail = 'Mostly clear'
elif clouds <= 50:
	cloudsDetail = 'Partly cloudy'
elif clouds <= 87:
	cloudsDetail = 'Mostly cloudy'
else:
	cloudsDetail = 'Overcast'

# Precipitation (API reports mm over the last hour, even in imperial mode)
precipIn = (rainMm + snowMm) / 25.4
if snowMm > 0 and rainMm > 0:
	precipDetail = 'Rain and snow, last hour'
elif snowMm > 0:
	precipDetail = 'Snow, last hour'
elif rainMm > 0:
	precipDetail = 'Rain, last hour'
else:
	precipDetail = 'None in the last hour'
if precipIn <= 0:
	precipBadge, precipBadgeClass = 'Dry', 'badge-ok'
elif precipIn < 0.1:
	precipBadge, precipBadgeClass = 'Light', 'badge-offline'
elif precipIn < 0.3:
	precipBadge, precipBadgeClass = 'Moderate', 'badge-warn'
else:
	precipBadge, precipBadgeClass = 'Heavy', 'badge-alarm'

# Sun: show whichever event comes next
sunDetail = ''
if sunrise and sunset:
	sunDetail = '%s daylight' % duration(sunset - sunrise)
now = dt or sunrise
if sunrise and sunset and now is not None and sunrise <= now < sunset:
	sunEvent, sunEventLabel = localTime(sunset, tz), 'sunset'
	sunDetail = u'Sunrise %s \u00b7 %s' % (localTime(sunrise, tz), sunDetail)
	sunBadge, sunBadgeClass = 'Sunset in ' + duration(sunset - now), 'badge-offline'
else:
	sunEvent, sunEventLabel = localTime(sunrise, tz), 'sunrise'
	sunDetail = u'Sunset %s \u00b7 %s' % (localTime(sunset, tz), sunDetail)
	sunBadge, sunBadgeClass = 'Night', 'badge-offline'

updated = '--'
if dt is not None:
	updated = datetime.datetime.utcfromtimestamp(int(dt) + int(tz)).strftime('%a %b %d | %I:%M %p').replace(' 0', ' ').replace('|', u'\u00b7')

city = g(w, 'name') or ''
country = g(w, 'sys', 'country')
return {
	'ok': True, 'wxClass': wxClass, 'accent': accent, 'icon': icon,
	'city': city + (', ' + country if country else ''),
	'condition': condDesc[:1].upper() + condDesc[1:],
	'updated': updated,
	'temp': '%d' % round(temp),
	'hiLo': u'H %d\u00b0  \u00b7  L %d\u00b0' % (round(hi), round(lo)),
	'feels': '%d' % round(feels), 'feelsDetail': feelsDetail,
	'feelsBadge': feelsBadge, 'feelsBadgeClass': feelsBadgeClass,
	'humidity': '%d' % humidity, 'humidityPct': '%d%%' % humidity,
	'humidityDetail': u'Dew point %d\u00b0F' % round(dewF),
	'humidityBadge': humidityBadge, 'humidityBadgeClass': humidityBadgeClass,
	'wind': '%d' % round(windSpeed), 'windDetail': windDetail, 'windRotation': int(windDeg + 180) % 360,
	'windBadge': windName, 'windBadgeClass': windBadgeClass,
	'pressure': pressureStr, 'pressureDetail': pressureDetail,
	'pressureBadge': pressureBadge, 'pressureBadgeClass': pressureBadgeClass,
	'visibility': visStr, 'visibilityDetail': visDetail,
	'visibilityBadge': visBadge, 'visibilityBadgeClass': visBadgeClass,
	'clouds': '%d' % clouds, 'cloudsPct': '%d%%' % clouds, 'cloudsDetail': cloudsDetail,
	'precip': '%.2f' % precipIn, 'precipUnit': 'in', 'precipDetail': precipDetail,
	'precipBadge': precipBadge, 'precipBadgeClass': precipBadgeClass,
	'sunEvent': sunEvent, 'sunEventLabel': sunEventLabel, 'sunDetail': sunDetail,
	'sunBadge': sunBadge, 'sunBadgeClass': sunBadgeClass,
}
